import Foundation
import Testing

@testable import MemosCore

/// The decoder is held to output produced by the ENCODER on the other side of the wire —
/// memos-ng's `app/services/blurhash_pure.py`, which is what writes the `blurhash` field this app
/// reads. Both vectors below were generated by running that encoder over a known image; neither
/// was produced by the code under test.
@Suite("BlurHash")
struct BlurHashTests {
    /// A hash with one component in each direction carries nothing but the DC term — the average
    /// colour, written as a 24-bit sRGB value in base83. So every pixel of the decode has to come
    /// back as EXACTLY that colour, which makes this vector an oracle the format itself defines
    /// rather than one this decoder gets to choose. `007Da1` is what the production encoder emits
    /// for a flat `#3E7C4F` image.
    @Test("a DC-only hash decodes to its exact sRGB colour in every pixel")
    func dcOnlyIsExact() throws {
        let pixels = try #require(BlurHash.decode("007Da1", width: 3, height: 2))
        #expect(pixels.count == 3 * 2 * 4)
        for index in stride(from: 0, to: pixels.count, by: 4) {
            #expect(pixels[index] == 0x3E)
            #expect(pixels[index + 1] == 0x7C)
            #expect(pixels[index + 2] == 0x4F)
            #expect(pixels[index + 3] == 255)
        }
        let average = try #require(BlurHash.averageColor("007Da1"))
        #expect(average.r == 0x3E)
        #expect(average.g == 0x7C)
        #expect(average.b == 0x4F)
    }

    /// Four-by-three components, the shape memos-ng encodes with. The hash was produced by that
    /// encoder from a 64x64 image whose red channel ramps left to right, green top to bottom and
    /// blue is flat — so the expected matrix is not only a fixture, it is a picture whose shape
    /// can be read: red climbs along every row, green climbs down every column, blue barely moves.
    @Test("a four-by-three hash decodes to the exact reference pixels")
    func gradientMatchesTheReference() throws {
        let expected: [[UInt8]] = [
            [15, 65, 101, 44, 63, 100, 74, 58, 98, 96, 57, 97, 121, 58, 98, 157, 60, 99, 197, 58,
                98, 228, 54, 95],
            [13, 57, 101, 43, 56, 100, 74, 53, 98, 96, 51, 97, 121, 53, 98, 157, 54, 99, 197, 53,
                98, 228, 49, 95],
            [8, 68, 101, 42, 68, 99, 74, 68, 97, 96, 68, 96, 121, 68, 97, 157, 68, 98, 197, 68,
                97, 228, 68, 94],
            [0, 121, 100, 40, 121, 98, 73, 121, 96, 96, 121, 95, 121, 121, 96, 156, 121, 97, 196,
                121, 96, 227, 121, 94],
            [0, 179, 99, 38, 179, 97, 73, 178, 95, 96, 177, 94, 121, 178, 95, 156, 178, 96, 195,
                178, 95, 226, 176, 93],
            [0, 221, 98, 36, 220, 97, 73, 218, 94, 96, 217, 93, 121, 218, 94, 156, 219, 95, 195,
                218, 94, 225, 216, 92],
        ]
        let pixels = try #require(
            BlurHash.decode("L$HV932Y$5Sghpazjtf7gcfjfQfj", width: 8, height: 6)
        )
        for row in 0..<6 {
            for column in 0..<8 {
                let offset = (row * 8 + column) * 4
                #expect(pixels[offset] == expected[row][column * 3])
                #expect(pixels[offset + 1] == expected[row][column * 3 + 1])
                #expect(pixels[offset + 2] == expected[row][column * 3 + 2])
            }
        }
    }

    @Test("the picture the hash describes is actually in the output")
    func theGradientIsRecognisable() throws {
        let pixels = try #require(
            BlurHash.decode("L$HV932Y$5Sghpazjtf7gcfjfQfj", width: 8, height: 6)
        )
        func red(_ x: Int, _ y: Int) -> Int { Int(pixels[(y * 8 + x) * 4]) }
        func green(_ x: Int, _ y: Int) -> Int { Int(pixels[(y * 8 + x) * 4 + 1]) }
        // red ramps left to right on every row, green ramps top to bottom in every column
        for y in 0..<6 {
            #expect(red(0, y) < red(3, y))
            #expect(red(3, y) < red(7, y))
        }
        for x in 0..<8 {
            #expect(green(x, 0) < green(x, 5))
        }
    }

    @Test("a malformed hash is nothing, not a crash")
    func malformedInputIsRejected() {
        #expect(BlurHash.decode("", width: 4, height: 4) == nil)
        #expect(BlurHash.decode("007Da", width: 4, height: 4) == nil)
        // right length for its own component count, wrong alphabet
        #expect(BlurHash.decode("00 Da1", width: 4, height: 4) == nil)
        // a 4x3 hash truncated to a 4x3 header with too few AC pairs
        #expect(BlurHash.decode("L$HV932Y$5Sghpaz", width: 4, height: 4) == nil)
        #expect(BlurHash.decode("007Da1", width: 0, height: 4) == nil)
        #expect(BlurHash.averageColor("00") == nil)
    }

    @Test("the sRGB transfer function round-trips every byte")
    func transferFunctionRoundTrips() {
        for byte in 0...255 {
            #expect(BlurHash.linearToSRGB(BlurHash.sRGBToLinear(byte)) == UInt8(byte))
        }
    }

    @Test("punch scales the AC terms away from the average, and zero flattens the hash")
    func punchFlattensToTheAverage() throws {
        let flat = try #require(
            BlurHash.decode("L$HV932Y$5Sghpazjtf7gcfjfQfj", width: 4, height: 4, punch: 0)
        )
        let average = try #require(BlurHash.averageColor("L$HV932Y$5Sghpazjtf7gcfjfQfj"))
        for index in stride(from: 0, to: flat.count, by: 4) {
            #expect(flat[index] == average.r)
            #expect(flat[index + 1] == average.g)
            #expect(flat[index + 2] == average.b)
        }
    }
}
